package dev.elsewhere.rivals.hrafnholt;

import net.minecraft.resources.Identifier;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Entry of the Hrafnholt rival module (package dev.elsewhere.rivals.hrafnholt): items, gear effects, units, bosses and the
 * field-tactics profile. Faction, unit, trim, banner and shop data live in data/elsewhere (generated by tools/gen_data.py).
 * {@link #init()} is idempotent; the merged core calls it.
 */
public final class HrafnholtContent {
	private HrafnholtContent() {}

	public static final Logger LOG = LoggerFactory.getLogger("elsewhere-hrafnholt");
	public static final Identifier FACTION = id("hrafnholt");
	private static boolean done;

	public static Identifier id(String path) {
		return Identifier.fromNamespaceAndPath("elsewhere", path);
	}

	public static void init() {
		if (done) return;
		done = true;
		Sfx3.init();
		HrafnholtItems.init();
		HrafnholtGear.init();
		HrafnholtUnits.init();
		dev.elsewhere.rivals.hrafnholt.boss.HrafnholtBosses.init();
		dev.elsewhere.rivals.hrafnholt.tactics.HrafnholtTactics.init();
		LOG.info("Elsewhere Hrafnholt loaded: {} items", HrafnholtItems.ALL.size());
	}
}
